/* Lunar Horizon basemap.
   Equirectangular colour mosaic of the Moon, baked into a classic script so it
   loads over file:// with no fetch and no CORS. The data: URI is same-origin,
   so drawing or sampling it can never taint a canvas (globe.js reads pixels).

   Source: NASA Scientific Visualization Studio, CGI Moon Kit,
   lroc_color_poles_1k.jpg (LRO LROC WAC mosaic, NASA/GSFC/ASU, public domain),
   https://svs.gsfc.nasa.gov/4720 — recompressed to JPEG q60, 1024x512.
   Longitude 0 (mean-Earth direction) at the image centre, north up. */
(function (root) {
  root.LUNAR_BASEMAP = {
    width: 1024,
    height: 512,
    projection: "equirectangular",
    source: "NASA SVS CGI Moon Kit (LROC WAC mosaic), svs.gsfc.nasa.gov/4720",
    src: "data:image/jpeg;base64,"
  };
})(typeof window !== "undefined" ? window : globalThis);
